# owner: platform
"""Seating rows ordered by last name."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _sort_key(student: Student) -> tuple:
    return (
        student.last_name.lower(),
        student.first_name.lower()
    )


def _rows(names: List[str], seats: int) -> List[str]:
    rows = []
    for index in range(0, len(names), seats):
        text = " | ".join(names[index:index + seats])
        rows.append(f"Row {index // seats + 1}: {text}")
    return rows


# ---
def seating_rows(
    students: List[Student], seats: int
) -> List[str]:
    if seats < 1 or not students:
        raise ProjectError("need students and seats")
    ordered = sorted(students, key=_sort_key)
    names = [f"{one.last_name}, {one.first_name}" for one in ordered]
    return _rows(names, seats)
EOF
