# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _make(last: str, first: str) -> Student:
    return Student("id", last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_sorted_rows(self):
        people = [
            _make("Halloway", "Juno"),
            _make("Dunmere", "Piet"),
            _make("Avery", "Sam")
        ]
        self.assertEqual(
            seating_rows(people, 2),
            [
                "Row 1: Avery, Sam | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_bad_seats(self):
        people = [_make("Avery", "Sam")]
        for seats in (0, -1):
            with self.assertRaises(ProjectError):
                seating_rows(people, seats)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)
